import json
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_3/projects/solver-trace-ablation/logs/workers/worker_code_component-count-trajectory-r2_20260520T092002.log') as f:
    lines = f.readlines()

# Get the last few user messages (tool results) and assistant messages
for i in range(max(0, len(lines)-10), len(lines)):
    line = lines[i].strip()
    if not line: continue
    try:
        obj = json.loads(line)
        t = obj.get('type', '?')
        if t == 'user':
            # Show tool results
            for c in obj.get('message', {}).get('content', []):
                if isinstance(c, dict) and c.get('type') == 'tool_result':
                    result_text = ''
                    for rc in c.get('content', []):
                        if isinstance(rc, dict):
                            result_text += rc.get('text', rc.get('data', ''))[:400]
                    is_error = c.get('is_error', False)
                    print(f'L{i} TOOL_RESULT (error={is_error}): {result_text[:500]}')
        elif t == 'assistant':
            for c in obj.get('message', {}).get('content', []):
                if isinstance(c, dict) and c.get('type') == 'text':
                    print(f'L{i} ASSISTANT: {c[\"text\"][:500]}')
    except:
        pass
